import { z } from "zod";

/** Dataset and run ids are uuid4 hex strings generated by the ML service. */
export const mlIdSchema = z
  .string()
  .regex(/^[a-f0-9]{32}$/, "must be an id returned by the ML service");

/** Body for POST /datasets/store (browser-parsed CSV fallback). */
export const storeBodySchema = z
  .object({
    filename: z.string().min(1).max(255),
    headers: z
      .array(z.string().trim().min(1, "column names cannot be blank"))
      .min(1)
      .refine((headers) => new Set(headers).size === headers.length, "column names must be unique"),
    rows: z.array(z.array(z.string())).min(1),
  })
  .superRefine((body, ctx) => {
    // A ragged row would otherwise fail later inside pandas with a vague error.
    const width = body.headers.length;
    const bad = body.rows.findIndex((row) => row.length !== width);
    if (bad !== -1) {
      ctx.addIssue({
        code: "custom",
        path: ["rows", bad],
        message: `row has ${body.rows[bad].length} values but there are ${width} columns`,
      });
    }
  });

/** Body for POST /train — mirrors the ML service TrainBody. */
export const trainBodySchema = z.object({
  datasetId: mlIdSchema,
  target: z.string().min(1),
  features: z.array(z.string()).min(1),
  task: z.enum(["classification", "regression"]),
  modelId: z.string().min(1),
  search: z.enum(["grid", "random"]).optional().nullable(),
  testSize: z.number().gt(0.05).lt(0.5).default(0.2),
  seed: z.number().int().optional().default(42),
  paramGrid: z.record(z.string(), z.unknown()).optional().nullable(),
  numericImpute: z.enum(["median", "mean"]).optional().default("median"),
  categoricalImpute: z.enum(["most_frequent", "constant"]).optional().default("most_frequent"),
  scale: z.boolean().optional().default(true),
  dropDuplicates: z.boolean().optional().default(true),
});

/** Body for POST /visualize/dataset. */
export const datasetFigureBodySchema = z.object({
  datasetId: mlIdSchema,
});

/** Body for POST /predict. */
export const predictBodySchema = z.object({
  runId: mlIdSchema,
  values: z
    .record(z.string(), z.union([z.string(), z.number()]))
    .refine((values) => Object.keys(values).length > 0, "enter at least one input value"),
});

export type StoreBody = z.infer<typeof storeBodySchema>;
export type TrainBody = z.infer<typeof trainBodySchema>;
export type DatasetFigureBody = z.infer<typeof datasetFigureBodySchema>;
export type PredictBody = z.infer<typeof predictBodySchema>;
